package com.example.trampaiimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.*import androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.foundation.shape.CircleShapeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Deleteimport androidx.compose.material3.*import androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spprivate val roxo = Color(0xFF5A4FCF)@Composablefun TelaHome(    servicos: List<Servico>,    aoRemover: (Servico) -> Unit,    irParaBusca: () -> Unit,    irParaPerfil: () -> Unit,    irParaUrgente: () -> Unit,    irParaDescricao: (Int) -> Unit) {    LazyColumn(        modifier = Modifier.fillMaxSize().background(Color(0xFFF5F5F5)),        contentPadding = PaddingValues(16.dp),        verticalArrangement = Arrangement.spacedBy(16.dp)    ) {        item {            Row(                modifier = Modifier.fillMaxWidth(),                horizontalArrangement = Arrangement.SpaceBetween,                verticalAlignment = Alignment.CenterVertically            ) {                Text("Taskly", color = roxo, fontSize = 24.sp, fontWeight = FontWeight.ExtraBold)                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {                    Button(onClick = irParaUrgente) { Text("🔔") }                    Button(onClick = irParaPerfil) { Text("👤") }                }            }        }        item {            Column {                Text("Bom dia, Alex", fontSize = 26.sp, fontWeight = FontWeight.Bold, color = Color.Black)                Text(                    "Quais tarefas podemos te ajudar a delegar hoje?",                    fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(top = 4.dp)                )            }        }        item {            Column {                Text("PRINCIPAIS CATEGORIAS", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.Gray)                Row(                    modifier = Modifier.padding(top = 8.dp),                    horizontalArrangement = Arrangement.spacedBy(8.dp)                ) {                    listOf("Limpeza", "Encanamento", "Design").forEachIndexed { i, nome ->                        Button(                            onClick = irParaBusca,                            colors = ButtonDefaults.buttonColors(containerColor = if (i == 0) roxo else Color.White)                        ) {                            Text(nome, color = if (i == 0) Color.White else Color.Black)                        }                    }                }            }        }        item {            Row(                modifier = Modifier.fillMaxWidth(),                horizontalArrangement = Arrangement.SpaceBetween,                verticalAlignment = Alignment.CenterVertically            ) {                Text("Recomendados Para Você", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = Color.Black)                Text("Ver Tudo", fontSize = 14.sp, color = roxo, modifier = Modifier.clickable { irParaBusca() })            }        }        if (servicos.isEmpty()) {            item { Text("Nenhum serviço ainda. Toque em Criar!", color = Color.Gray) }        }        items(servicos, key = { it.id }) { servico ->            CardServico(                servico = servico,                aoClicar = { irParaDescricao(servico.id) },                aoRemover = { aoRemover(servico) }            )        }    }}@Composableprivate fun CardServico(servico: Servico, aoClicar: () -> Unit, aoRemover: () -> Unit) {    Card(        modifier = Modifier.fillMaxWidth().clickable { aoClicar() },        shape = RoundedCornerShape(12.dp),        colors = CardDefaults.cardColors(containerColor = Color.White)    ) {        Box(modifier = Modifier.fillMaxWidth().height(120.dp).background(Color.LightGray)) {            IconButton(                onClick = aoRemover,                modifier = Modifier                    .align(Alignment.TopEnd)                    .padding(8.dp)                    .size(36.dp)                    .background(Color.White, CircleShape)            ) {                Icon(Icons.Default.Delete, contentDescription = "Remover", tint = Color(0xFFD32F2F))            }        }        Column(modifier = Modifier.padding(12.dp)) {            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {                Text(                    servico.titulo, fontWeight = FontWeight.Bold, fontSize = 15.sp,                    color = Color.Black, modifier = Modifier.weight(1f).padding(end = 8.dp)                )                Text(servico.valorFormatado, fontWeight = FontWeight.Bold, fontSize = 15.sp, color = roxo)            }            Row(                modifier = Modifier.fillMaxWidth().padding(top = 8.dp),                horizontalArrangement = Arrangement.SpaceBetween,                verticalAlignment = Alignment.CenterVertically            ) {                Row(verticalAlignment = Alignment.CenterVertically) {                    Box(modifier = Modifier.size(20.dp).background(Color.Gray, CircleShape))                    Text("  ${servico.autor}", fontSize = 13.sp, color = Color.DarkGray)                }                Text(servico.categoria, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = Color.Black)            }            Text("📍 ${servico.localizacao}", fontSize = 11.sp, color = Color.Gray, modifier = Modifier.padding(top = 8.dp))        }    }}